// Remove ```json, ``` and trim whitespace
const cleaned = text
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .replace(/;/,'')
  .trim();
//{{ JSON.parse($json.output).SQL_Script }}

return  [{json: JSON.parse(cleaned)}][0];;

const raw = $input.first().json.output;

// Convert escaped JSON string into real JSON
const parsed = JSON.parse(raw);

// Convert array to n8n items
return parsed.map(row => {

  const nba = row.NBA_DETAILS || {};

  const nbaText =
    `Immediate Fix: ${nba["Immediate Fix"] || ""}\n` +
    `Preventive Measure: ${nba["Preventive Measure"] || ""}\n` +
    `Alternate Strategy: ${nba["Alternate Strategy"] || ""}`;

  return {
    json: {
      MONTH: row.MONTH,
      CATEGORY: row.CATEGORY,
      SUB_CATEGORY: row.SUB_CATEGORY,
      SALES: row.SALES,
      ANOMALY_DETAILS: row.ANOMALY_DETAILS,
      RCA_DETAILS: row.RCA_DETAILS,
      NBA_DETAILS: nbaText
    }
  };
});

